mapper.select:
SELECT COUNT(*) > 0
FROM sto_yt_delivery
WHERE code = #{code}
AND is_deleted = 0

    AND id != #{excludeId}

select b.* from sto_yt_delivery_item a left join sto_yt_delivery b on a.delivery_id=b.id
where a.is_deleted=0 and b.is_deleted=0
and a.order_sub_id=#{orderSubId} and a.delivery_id !=#{deliveryId}

SELECT DISTINCT d.*,syc.name as customerName, (select name from sto_yt_transport_company where id = d.transport_company_id) as transportCompanyName, (select url from sys_storage where id=d.transport_order_file_id) as transportOrderFileUrl, (select nick_name from sys_user where user_id = syc.belong_employee_id) as salesEmployeeName -- syo.code as orderCode FROM sto_yt_delivery d LEFT JOIN sto_yt_delivery_item di ON d.id = di.delivery_id AND di.is_deleted = 0 LEFT JOIN sal_yt_order_sub syos ON di.order_sub_id = syos.id AND syos.is_deleted = 0 LEFT JOIN sal_yt_order syo ON syos.order_id = syo.id AND syo.is_deleted = 0 LEFT JOIN sal_yt_customer syc ON syo.customer_id = syc.id AND syc.is_deleted = 0 WHERE d.is_deleted = 0 AND di.id IS NOT NULL
AND d.code LIKE CONCAT('%', #{code}, '%')
AND syo.is_collected_shipping_cost = #{isCollectedShippingCost}
AND d.customer_id = #{customerId}
AND syc.name LIKE CONCAT('%', #{customerName}, '%')
AND syos.sub_code LIKE CONCAT('%', #{subCode}, '%')
AND d.address_id = #{addressId}
AND d.status = #{status}
AND d.receive_status = #{receiveStatus}
AND d.package_code like concat('%', #{packageCode} ,'%')
AND syc.belong_employee_id in (select user_id from sys_user where nick_name like concat('%',#{salesEmployeeName},'%'))
AND d.transport_company_id in (select id from sto_yt_transport_company where name like concat('%',#{transportCompanyName},'%'))
AND syo.id = #{orderId}
AND syo.code LIKE CONCAT('%', #{orderCode}, '%')
ORDER BY d.create_time DESC
